t.script:
//
document.addEventListener('DOMContentLoaded', function () {
    var tbody      = document.getElementById('tbody_lignes');
    var btnAjouter = document.getElementById('btn_ajouter_ligne');
    var csrfToken  = document.querySelector('[name=csrf_token]').value;
    var lineIndex  = 1;

    var selectProd0     = tbody.querySelector('.select-product');
    var produitOptions  = selectProd0 ? selectProd0.innerHTML : '';

    function buildCondOptions(conds) {
        var opts = '<option value="">-- Choisir --</option>';
        conds.forEach(function (c) {
            opts += '<option value="' + c.id + '">' + c.name + '</option>';
        });
        return opts;
    }

    function attachListeners(row) {
        var selProd  = row.querySelector('.select-product');
        var selCond  = row.querySelector('.select-cond');
        var btnSuppr = row.querySelector('.btn-suppr');

        if (selProd) {
            selProd.addEventListener('change', function () {
                var productId = this.value;
                selCond.innerHTML = '<option value="">Chargement...</option>';
                if (!productId) {
                    selCond.innerHTML = '<option value="">-- Choisir produit --</option>';
                    return;
                }
                fetch('/my/gica/devis/conditionnements', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-CSRFToken': csrfToken,
                    },
                    body: JSON.stringify({
                        jsonrpc: '2.0', method: 'call', id: 1,
                        params: { product_tmpl_id: parseInt(productId) },
                    }),
                })
                .then(function (r) { return r.json(); })
                .then(function (data) {
                    var conds = (data.result || {}).conditionnements || [];
                    selCond.innerHTML = buildCondOptions(conds);
                })
                .catch(function () {
                    selCond.innerHTML = '<option value="">Erreur</option>';
                });
            });
        }

        if (btnSuppr) {
            btnSuppr.addEventListener('click', function () {
                var rows = tbody.querySelectorAll('.ligne-devis');
                if (rows.length > 1) row.remove();
            });
        }
    }

    tbody.querySelectorAll('.ligne-devis').forEach(attachListeners);

    if (btnAjouter) {
        btnAjouter.addEventListener('click', function () {
            var idx = lineIndex++;
            var row =
                '<tr class="ligne-devis" data-index="' + idx + '">' +
                '<td><select name="product_' + idx + '" class="form-select form-select-sm select-product" required style="pointer-events:auto;">' +
                produitOptions + '</select></td>' +
                '<td><select name="cond_' + idx + '" class="form-select form-select-sm select-cond" required style="pointer-events:auto;"><option value="">-- Choisir produit --</option></select></td>' +
                '<td><input type="number" name="qty_' + idx + '" step="0.01" min="0.01" class="form-control form-control-sm" style="pointer-events:auto;" required/></td>' +
                '<td><button type="button" class="btn btn-sm btn-danger btn-suppr" style="pointer-events:auto;"><i class="fa fa-trash"/></button></td>' +
                '</tr>';
            tbody.insertAdjacentHTML('beforeend', row);
            attachListeners(tbody.lastElementChild);
        });
    }
});
//
